<span class="line"><span style="color:#E06C75;">    isEncrypted</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">item</span><span style="color:#ABB2BF;">.</span><span style="color:#E06C75;">isEncrypted</span><span style="color:#ABB2BF;">,</span></span>
